&lt;p data-path-to-node=&quot;5,0,0&quot;&gt;&lt;span data-path-to-node=&quot;5,0,0,1&quot;&gt;&lt;span class=&quot;citation-2851&quot;&gt;Formulate, evangelise, and drive adoption of the product security strategy&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;5,1,0&quot;&gt;&lt;span data-path-to-node=&quot;5,1,0,1&quot;&gt;&lt;span class=&quot;citation-2850&quot;&gt;Assess, advise on, and increase the security maturity posture&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
