&lt;li&gt;
&lt;p data-path-to-node=&quot;5,13,0&quot;&gt;&lt;span data-path-to-node=&quot;5,13,0,1&quot;&gt;&lt;span class=&quot;citation-2838&quot;&gt;Identify skills gaps and facilitate knowledge sharing across the organization&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
